function UIActionTeamDestoryDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local canvas = KTool.GetComponent(UINavigationBarRoot.Instance.gameObject, typeof(CS.UnityEngine.Canvas))
        canvas.enabled = true
    
        local t = RegionQuestMgr:GetInstance():GetHouseInfo()
        if not t then
            return
        end
        self.activityType = checkNumber(t.activityType)
        self.activityContetnId = checkNumber(t.activityContentId)
        self.activityUuid = checkNumber(t.activityUuid)
        self.activityPrefabId = checkNumber(t.activityPrefabId)
        self._curQuestId = checkNumber(t.questId)
        self._bossTypeId = checkNumber(t.bossTypeId)

        if self._curQuestId <= 0 or self._bossTypeId < 0 then
            return
        end
        self.comp = AnnihilationUtils.GetComponent(self.activityPrefabId)
        
        self.teamRoomUITypeId = self.comp:GetTeamUITypeId()

        -- 加载场景和角色模型
        coroutine.yield(RegionQuestMgr:GetInstance():EntryRegionTeamScene())
        RegionQuestMgr:GetInstance():SetSceneActive(true)
        GameUtils.HidePreviousDialogs(self.controller)
        KCookie.Set(Constants.UICacheDataKeys.OVERSEA_ANNIHILATION_KEY, 1)
        -- 绘制界面
        self:FillDialog()
        
        -- 进入聊天房间
        local useVoiceRoom = self.comp:UseVoiceRoom()
        RegionQuestMgr:GetInstance().useVoiceRoom = useVoiceRoom
        if useVoiceRoom then
            local t = RegionQuestMgr:GetInstance():GetHouseInfo()
            local social = AppService:GetInstance():GetSocialLine()
            social:EnterVoiceRoom(t.roomId)
        end
    end))
    return coWait
end

function UIActionTeamDestoryDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopRightProjection(0)
        CfUtils.SetUICameraProjection(true, 26)    -- 设置UI相机的透视模式和fov
        self:OnRegionTeamQuite()

        local cam = RegionQuestMgr:GetInstance():GetCurrentSceneCam()
        if not isNull(cam) then 
            local urpBase = cam:GetComponent(typeof(URPBaseCamera))
            urpBase:CopyCamera() 
        end

        local imOwner = RegionQuestMgr:GetInstance():GetIsHouseOwn()
        if imOwner then
            -- 开房时记录最后进入的Boss和关卡
            GameUtils.SaveInt(string.format("AnnihilationLastBoss_%s_%d_%d", GameUtils.GetPlayerId(), self.activityPrefabId, self.activityContetnId), self._bossTypeId)
            GameUtils.SaveInt(string.format("AnnihilationLastBossQuest_%s_%d_%d_%d", GameUtils.GetPlayerId(), self.activityPrefabId, self.activityContetnId, self._bossTypeId), self._curQuestId)
        end
    end))
    return coWait
end

