function UIActionTeamDestoryDialog:HandleBackAction()
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            -- cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
            self._isClearScene = true
            local social = AppService:GetInstance():GetSocialLine()
            social:ExitTeamRoom()
            if self.comp:UseVoiceRoom() then
                social:ExitVoiceRoom()
            end
            cs_coroutine.yield_return(self:OnCaptureAction())
            RegionQuestMgr:GetInstance():QuitReq()
            print("[歼灭战] mgr quit req HandleBackAction")
            RegionQuestMgr:GetInstance():QuitRegionTeamScene()
        end)
    end)
end

