function UIActionTeamDestoryDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._co ~= nil then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        self:StopShowRecruitTime()
        self.tc_RecruitProtect:Stop()
        Events.RemoveListener(Constants.EventNames.RegionTeamInviteResult, self.EventRegionTeamInviteResult)
        Events.RemoveListener(Constants.EventNames.RegionTeamReadey, self.EventRegionTeamReadey)
        Events.RemoveListener(Constants.EventNames.RegionTeamQuite, self.EventRegionTeamQuite)
        Events.RemoveListener(Constants.EventNames.RefeshTeamMember, self.EventRegionTeamSet)

        Events.RemoveListener(Constants.EventNames.RegionLoadBegin, self.EventRegionLoadBegin)
        Events.RemoveListener(Constants.EventNames.RegionLoading, self.EventRegionLoading)

        Events.RemoveListener(Constants.EventNames.RegionTeamMatch, self.EventRegionTeamMatch)
        
        Events.RemoveListener(Constants.EventNames.ExecuteBackHome, self.EventExecuteBackHome)
        Events.RemoveListener(Constants.EventNames.RegionRecruitResult, self.EventRegionRecruitResult)
        Events.RemoveListener(Constants.EventNames.ONAPPQUIT, self.EventOnAppQuit)
        Events.RemoveListener(Constants.EventNames.TeamRoomReconnectRefreshDisplay, self.EventReconnectRefreshDisplay)
        Events.RemoveListener(Constants.EventNames.DreamAdventuresHomeDataUpdate, self.EventUpdateResources)

        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.OverseaChat)
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end
        CfUtils.SetTopCommonCb()

        --if self._isClearScene and not self._enterBattle then    -- 进入战斗的时候不用打开主界面，否则退出战斗的时候也会自动打开主界面，导致出bug
        --    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        --end
        GameUtils.ShowPreviousDialogs(self.controller)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIActionTeamDestoryDialog:OnCaptureAction()
    if self._isClearScene then
        -- capture screen
        local effectBg = self.controller.gameObject:GetComponent(typeof(UIEffectCapturedImage))
        if effectBg then
            effectBg:Capture()
        end
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        cs_coroutine.yield_return(RegionQuestMgr:GetInstance():Clear())
    end
end

