--- 实时匹配奖励
function UIActionTeamDestoryDialog:FillRealtimeReward()
    if isNull(self.GoodGroup) then
        return
    end

    local vo = RewardConfMgr:GetInstance():GetQuestRewardVo(self._curQuestId)
    if isNull(vo) then
        return
    end

    local rewardIdList = vo.playerRewardItem
    local rewardNumList = vo.playerRewardNum

    local rewards = parse_rewards(rewardIdList, rewardNumList, ";")

    if table.count(rewards) <= 0 then
        KTool.SetActive(self.GoodGroup, false)
        return
    end

    print("[实时奖励]", table.dump(rewards))
    
    local luaPath = "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestroyRealtimeReward"
    ---@type UIActionTeamDestroyRealtimeReward
    local lt = CfUtils.GetLuaScr(self.GoodGroup.gameObject, luaPath)
    lt:Refresh(rewards)

    local activeState = false
    local desc = ""
    local state = RegionQuestMgr:GetInstance():GetHouseState()
    if state == HouseState.None or state == HouseState.InviteWaiting then
        -- 没人
        activeState = false
        desc = localize("邀请在线好友一起时激活")
    elseif state == HouseState.InviteSuc or state == HouseState.ReadySuc then
        -- 有人
        local isRobot = RegionQuestMgr:GetInstance():IsOtherRobot()
        if isRobot == 1 then
            -- 机器人
            activeState = false
            desc = localize("邀请在线好友一起时激活")
        else
            -- 真人
            local rewardTimes = checkNumber(self.comp.remainCreateRewardTimes)  -- 剩余奖励次数
            if rewardTimes > 0 then
                -- 有剩余次数
                activeState = true
            else
                -- 没有剩余次数了
                activeState = false
                desc = localize("今日奖励次数已用完")
            end
        end
    end
    lt:SetActive(activeState)
    lt:OnInActiveClicked(function()
        GameUtils.Toast(desc)
    end)
end

--- 多倍消耗的列表
function UIActionTeamDestoryDialog:FillRewardTimesFilter()
    if isNull(self.AlignNode) then
        return
    end
    local rewardTimes = checkNumber(self.comp.remainCreateRewardTimes)  -- 剩余奖励次数
    if rewardTimes <= 0 then
        KTool.SetActive(self.AlignNode, false)
        return
    end
    ---@type CommonFilter
    local lt = CfUtils.GetLuaScr(self.AlignNode.gameObject, "Game.UI.Common.CommonFilter")
    if isNotNull(lt) then
        KTool.SetActive(self.AlignNode, true)

        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
        if isNull(vo) then
            printError("id %s 找不到关卡信息", self._curQuestId)
            return
        end
        local costItem = vo.costItem
        local costNum = (vo.costNum + vo.costNumLose)

        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(costItem)
        if isNull(goodsVo) then
            printError("id %s 找不到道具信息", costItem)
            return
        end
        -- 构造列表数据
        local filterData = {}
        for i = 1, rewardTimes, 1 do
            local data = {
                imgPath = goodsVo.photoPath,
                text1 = localize("_num_倍", {_num_ = i}),
                text2 = tostring(costNum * i)
            }
            table.insert(filterData, data)
        end
        lt:SetOnValueChanged(function(index)
            RegionQuestMgr:GetInstance():SetConsumeTimes(index)
        end)
        local times = RegionQuestMgr:GetInstance():GetConsumeTimes()
        lt:RefreshPanel(filterData, times)
    end
end

function UIActionTeamDestoryDialog:FillMicInfo()
    local useVoice = false  -- self.comp:UseVoiceRoom()
    KTool.SetActive(self.CommonVoiceChatBtn.transform.parent, useVoice)
    if useVoice then
        local lb = GetLuaBehaviour(self.CommonVoiceChatBtn.gameObject, "Game.Behaviours.CommonMicBtn")
        lb.Env:SetPlayerId(checkNumber(GameUtils.GetPlayerId()))
        lb.Env:SetCallbackOnBtnStageChanged(function(state)
            self.STxt_BtnOpenState.Status = state and 1 or 2
        end)
    end
end

function UIActionTeamDestoryDialog:FillRewardTimesAndConsumeInfo()
    if self.activityType == 0 then
        -- 剩余奖励次数
        local rewardTimes = checkNumber(self.comp.remainCreateRewardTimes)
        self.Txt_RemainTimes.text = tostring(rewardTimes)
        
        -- 奖励次数清零以后，不显示消耗道具提示
        KTool.SetActive(self.RT_ConsumePop, rewardTimes > 0)
    else
        local useHP = RegionQuestMgr:GetInstance():GetUseHP()
        KTool.SetActive(self.RT_ConsumePop, useHP == 1)
    end
    
    -- 刷新消耗道具提示
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    CfUtils.FillCommonBtnConsumePopNode(self.RT_ConsumePop, vo.costItem, (vo.costNum + vo.costNumLose))
end

--- 绘制关卡信息
function UIActionTeamDestoryDialog:FillQuestInfo()
    -- 关卡名
    local typeVo = self.comp:GetTypeVo(self._bossTypeId)
    if not typeVo then
        return
    end
    CfUtils.FillText(self.TxtTitle, typeVo.name)
    
    -- 推荐战力
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if not vo then
       return
    end
    local recommendPower = vo.proposalLevel
    CfUtils.FillText(self.Txt_RecommandPower, recommendPower)
    CfUtils.SetColor(self.Txt_RecommandPower, self:IsOverRecommendPower() and Color.white or XLuaUtils.HexToColor("#ff6363"))
end

--- 绘制房主信息
function UIActionTeamDestoryDialog:FillHouseOwnerInfo()
    -- 看房主是不是我自己
    local imOwner = RegionQuestMgr:GetInstance():GetIsHouseOwn()

    local scr = CfUtils.GetLuaScr(self.PlayerGroup2, "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestoryNode")
    if scr then
        local data = RegionQuestMgr:GetInstance():GetHouseOwnerInfo()
        scr:Refresh(data, imOwner, true, function()
            -- 点击编队按钮回调
            if self._isBegin then
                return
            end

            RegionQuestMgr:GetInstance():SetSceneActive(false)
            self._isClearScene = false
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curQuestId, isOwn = imOwner and 1 or 0} }, {
                { id = self.teamRoomUITypeId },
            })
        end, function()
            local isMyself = imOwner
            if not isMyself then
                if data.playerInfo.playerId > 0 then
                    -- 直接进入 他人的 个人信息界面2D版 
                    self._isClearScene = false
                    GameUtils.ShowPlayerInfo( data.playerInfo.playerId, {{ id = self.teamRoomUITypeId}} )
                end
            end
        end, self.comp:UseVoiceRoom())
        -- 房主默认显示准备完成
        scr:FillReadyInfo(1)
    end
end

--- 绘制队员的信息
function UIActionTeamDestoryDialog:FillHouseMemberInfo()
    CfUtils.SetActive(self.InvateInfo, false)
    CfUtils.SetActive(self.WaitingGroup, false)
    CfUtils.SetActive(self.PlayerGroup, false)

    local state = RegionQuestMgr:GetInstance():GetHouseState()
    if state == HouseState.None or state == HouseState.InviteWaiting then
        CfUtils.SetActive(self.InvateInfo, true)
    --elseif state == HouseState.InviteWaiting then
    --    CfUtils.SetActive(self.WaitingGroup, true)
    elseif state == HouseState.InviteSuc or state == HouseState.ReadySuc then
        self:FillHouseMember()
        CfUtils.SetActive(self.PlayerGroup, true)
    end
end

--- 绘制队员
function UIActionTeamDestoryDialog:FillHouseMember()
    -- 看房客是不是我自己
    local imMember = not RegionQuestMgr:GetInstance():GetIsHouseOwn()

    local scr = CfUtils.GetLuaScr(self.PlayerGroup, "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestoryNode")
    if scr then
        local data = RegionQuestMgr:GetInstance():GetHouseMemberInfo()
        scr:Refresh(data, imMember, false, function()
            -- 点击编队按钮回调，查看别人的编队
            self._isClearScene = false

            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curQuestId, isOwn = imMember and 1 or 0 } }, {
                { id = self.teamRoomUITypeId },
            })
        end, function()
            local isMyself = imMember
            if not isMyself then
                if data.playerInfo.playerId > 0 then
                    -- 直接进入 他人的 个人信息界面2D版 
                    self._isClearScene = false
                    GameUtils.ShowPlayerInfo( data.playerInfo.playerId, {{ id = self.teamRoomUITypeId}} )
                end
            end
        end, self.comp:UseVoiceRoom())
        -- 绘制准备状态
        local info = RegionQuestMgr:GetInstance():GetHouseMemberInfo()
        scr:FillReadyInfo(checkNumber(info.readyState))
    end
end

-- 点击准备按钮回调
function UIActionTeamDestoryDialog:OnBtnReady()
    -- 点击准备按钮回调
    if self._isBegin then
        return
    end

    local data = RegionQuestMgr:GetInstance():GetOwnInfo()
    local t = {
        ready = ((checkNumber(data.readyState) == 0) and 1 or 0)
    }
    -- 请求更新准备状态
    RegionQuestMgr:GetInstance():ReadyReq(t)
end

--- 服务器下发准备状态
function UIActionTeamDestoryDialog:OnRegionTeamReadey()
    self:FillReadyInfo()
    self:FillBtnStartInfo()
end

function UIActionTeamDestoryDialog:FillReadyInfo()
    local scr = CfUtils.GetLuaScr(self.PlayerGroup, "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestoryNode")
    if scr then
        local data = RegionQuestMgr:GetInstance():GetHouseMemberInfo()
        scr:FillReadyInfo(data.readyState)
        CfUtils.SetActive(self.LeftGroup, checkNumber(data.readyState) == 1)
    end
end

--开始按钮
function UIActionTeamDestoryDialog:FillBtnStartInfo()
    local comp = AnnihilationUtils.GetComponent(self.activityPrefabId)
    local animPrefix = comp:GetTeamRoomDialogAnimationPrefix()

    local isHouseOwn = RegionQuestMgr:GetInstance():GetIsHouseOwn()
    if isHouseOwn then
        CfUtils.FillText(self.TxtStart, localize("开始"))  
        CfUtils.PlayAnimation(self.StartGroup, animPrefix .. "_StartGroup_Ready")
        SetButtonAction(self.BtnStart, Bind(self,self.OnBtnStart))
    else
        local houseMemberState = RegionQuestMgr:GetInstance():GetHouseMemberInfo()
        local readyState = checkNumber(houseMemberState.readyState)
        if readyState == 0 then
            CfUtils.FillText(self.TxtStart, localize("准备"))
            CfUtils.PlayAnimation(self.StartGroup, animPrefix .. "_StartGroup_Ready")
            SetButtonAction(self.BtnStart, Bind(self, self.OnBtnReady))
        elseif readyState == 1 then
            CfUtils.FillText(self.TxtStart, localize("取消准备"))
            CfUtils.PlayAnimation(self.StartGroup, animPrefix .. "_StartGroup_Ready")
            SetButtonAction(self.BtnStart, Bind(self, self.OnBtnReady))
        end
    end
end

--- 房客收到需要退出房间的消息
function UIActionTeamDestoryDialog:OnRegionTeamQuite()
    local kickoutState = RegionQuestMgr:GetInstance():GetOwnKickOutState()
    if kickoutState > 0 then
        local str = ""
        if kickoutState == 1 then
            str = localize("被踢出房间")
        elseif kickoutState == 2 then
            str = localize("房间已解散")
        elseif kickoutState == 3 then
            str = localize("发生网络波动，请重新加入房间")
        end
        -- 如果聊天界面开着，先关闭聊天界面
        local chatDialog = GameUtils.GetDialog(Constants.UITypeIds.OverseaChatMainDialog)
        if isNotNull(chatDialog) then
            UIModule.CloseDialog(chatDialog)
        end
        GameUtils.SecondConfirm(str, function()
            GameUtils.ShowBlackOverlay(nil, function()
                self._isClearScene = false
                local social = AppService:GetInstance():GetSocialLine()
                social:ExitTeamRoom()
                if self.comp:UseVoiceRoom() then
                    social:ExitVoiceRoom()
                end
                cs_coroutine.yield_return(self:OnCaptureAction())
                RegionQuestMgr:GetInstance():QuitReq()
                RegionQuestMgr:GetInstance():QuitRegionTeamScene()
            end)
        end, function()
            GameUtils.ShowBlackOverlay(nil, function()
                self._isClearScene = false
                local social = AppService:GetInstance():GetSocialLine()
                social:ExitTeamRoom()
                if self.comp:UseVoiceRoom() then
                    social:ExitVoiceRoom()
                end
                cs_coroutine.yield_return(self:OnCaptureAction())
                RegionQuestMgr:GetInstance():QuitReq()
                RegionQuestMgr:GetInstance():QuitRegionTeamScene()
            end)
        end)
    end
end

--- 当收到踢人消息时
function UIActionTeamDestoryDialog:OnRegionTeamKickout()
    self:FillHouseMemberInfo()
    self:FillQuestInfo()   -- 更新总战力的颜色
    self:FillRealtimeReward()
end

--@region 匹配
--匹配
function UIActionTeamDestoryDialog:OnBtnMatching()
    RegionQuestMgr:GetInstance():StartHouseMatchingReq()
end 

--取消匹配
function UIActionTeamDestoryDialog:OnBtnCancelMatching()
    RegionQuestMgr:GetInstance():CancelHouseMatchingReq()
    self:OnMatchingEnd(false)
end

--s收到加入匹配结果
function UIActionTeamDestoryDialog:OnRegionTeamMatch(body)
    --成功, 可以开始匹配了
    if checkNumber(body.result) == 0 then
        self._matchingTime = ActionUtils.GetDefaultCountDown()
        CfUtils.FillText(self.TextNumber, self._matchingTime)

        CfUtils.SetActive(self.ActionTeamDestoryMatchDialog, true)
        CfUtils.SetActive(self.Root, false)
        self._isBeginMatching = true
        self.LT_MatchPanel:StartCountDown(self._matchingTime, function()
            self:OnBtnCancelMatching()
        end)

        -- CfUtils.PlayAnimator(self.ActionTeamDestoryMatchDialog.transform:Find("Root"), "Match")
    else
        CfUtils.SetActive(self.ActionTeamDestoryMatchDialog, false)
        CfUtils.SetActive(self.Root, true)
        self._isBeginMatching = false
        GameUtils.Toast(localize("加入匹配失败"))
    end
end

function UIActionTeamDestoryDialog:OnMatchingEnd(isSuc, cb)
    if isSuc then
        self._isBeginMatching = false
        self.LT_MatchPanel:PlayComplete(function()
            CfUtils.SetActive(self.Root, true)
            CfUtils.SetActive(self.ActionTeamDestoryMatchDialog, false)
            CfUtils.PlayAnimation(self.Root, "ActionTeamDestoryDialog_InvateGroupBack")
            if cb then
                cb()
            end
        end)
    else
        CfUtils.SetActive(self.ActionTeamDestoryMatchDialog, false)
        CfUtils.SetActive(self.Root, true)
        self._isBeginMatching = false
    end
end
--@endregion

function UIActionTeamDestoryDialog:OnExecuteBackHome()
    local social = AppService:GetInstance():GetSocialLine()
    social:ExitTeamRoom()
    if self.comp:UseVoiceRoom() then
        social:ExitVoiceRoom()
    end
end

--- 点击邀请按钮
function UIActionTeamDestoryDialog:OnBtnPeopleInvate()
    if self._isBegin then
        return
    end

    self._isClearScene = false 

    -- 检查是否有好友
    RegionQuestMgr:GetInstance():OverseaRegionalBossInvitePanelReq(2, function(data)
        local hasFriends = #checkTable(data.data) > 0
        local index = hasFriends and 1 or 3 -- 有好友显示好友，没好友显示AI机器人
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionTeamInvitePopupDialog, parameters = {selectIndex = index, comp = self.comp}}, {
            {id = self.teamRoomUITypeId }
        })
    end)
end

--- 有邀请结果来了 刷新伙伴信息
function UIActionTeamDestoryDialog:OnRegionTeamInviteResult(data)
    if self._isBeginMatching then
        self:OnMatchingEnd(true, function()
            self:FillHouseMemberInfo()
            self:FillQuestInfo()
            self:FillRealtimeReward()
        end)
    else
        self:FillHouseMemberInfo()
        self:FillQuestInfo()
        self:FillRealtimeReward()

        if isNotNull(data) then
            CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_anzhuang)
        end
    end
end

--- 点击开始按钮(只有房主能点击开始)
function UIActionTeamDestoryDialog:OnBtnStart()
    if self._isBegin then
        return
    end

    --不是自己的房间
    local isHouseOwn = RegionQuestMgr:GetInstance():GetIsHouseOwn()
    if not isHouseOwn then
        return
    end

    local state = RegionQuestMgr:GetInstance():GetHouseState()
    -- 单人开始
    if state == HouseState.None
    or state == HouseState.InviteWaiting then
        if not RegionQuestMgr:GetInstance():IsTeamSet(true) then
            GameUtils.Toast(localize("编队为空"))
            return
        end
        
        GameUtils.SecondConfirm(localize("是否单人进入战斗？"), 
        function()
            RegionQuestMgr:GetInstance():StartBattleReq()
        end,
        nil,
        self:IsOverRecommendPower() and "" or localize("当前战斗力未达到推荐战力"))
    -- 双人开始
    elseif state == HouseState.ReadySuc
    or state == HouseState.InviteSuc then
        if not RegionQuestMgr:GetInstance():IsTeamSet(true) then
            GameUtils.Toast(localize("编队为空"))
            return
        end
        RegionQuestMgr:GetInstance():StartBattleReq()
    -- -- 有人没准备
    -- elseif state == HouseState.InviteSuc then
    --     -- 队友没准备
    --     GameUtils.Toast(localize("请等待队友准备完成"))
    end
end

--- 判断队伍战力是否超过推荐战力
function UIActionTeamDestoryDialog:IsOverRecommendPower()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if not vo then
        return false
    end
    local recommendPower = vo.proposalLevel

    local myPower = RegionQuestMgr:GetInstance():GetOwnInfo().mainTeamSet.totalCombatVal

    local otherPower = 0
    local otherInfo = RegionQuestMgr:GetInstance():GetOtherInfo()
    if otherInfo and otherInfo.mainTeamSet and otherInfo.mainTeamSet.totalCombatVal then
        otherPower = checkNumber(otherInfo.mainTeamSet.totalCombatVal) 
    end

    return (checkNumber(myPower) + otherPower) >= checkNumber(recommendPower)
end

--- 绘制招募按钮
function UIActionTeamDestoryDialog:FillBtnRecruit()
    local state = RegionQuestMgr:GetInstance():GetRecruitState()
    self:SetRecruitBtnState(state, false)
end

function UIActionTeamDestoryDialog:SetRecruitBtnState(state, showTrail)
    if state == 0 then
        self.TxtRecruit.text = localize("公开招募")
        KTool.SetActive(self.BtnCancelResruit, false)
        KTool.SetActive(self.TxtRecruitTime, false)
    elseif state == 1 then
        self.TxtRecruit.text = localize("取消招募")
        KTool.SetActive(self.BtnCancelResruit, true)
        KTool.SetActive(self.TxtRecruitTime, true)
        self:StartShowRecruitTime()
    end
    -- 动效
    self:EffectOnRecruitBtnStateChanged(state, showTrail)
end

function UIActionTeamDestoryDialog:StartShowRecruitTime()
    if isNotNull(self.co_showRecruitTime) then
        return
    end
    -- 开始计时
    local time = RegionQuestMgr:GetInstance():GetRecruitTime()
    self.TxtRecruitTime.text = localize("等待中_num_s", {_num_ = time})

    self.co_showRecruitTime = cs_coroutine.start(function()
        while true do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            local time = RegionQuestMgr:GetInstance():GetRecruitTime()
            self.TxtRecruitTime.text = localize("等待中_num_s", {_num_ = time})
        end
        self.co_showRecruitTime = nil
    end)
end

function UIActionTeamDestoryDialog:StopShowRecruitTime()
    if isNotNull(self.co_showRecruitTime) then
        cs_coroutine.stop(self.co_showRecruitTime)
        self.co_showRecruitTime = nil
    end
end

--- 请求修改招募状态
function UIActionTeamDestoryDialog:OnBtnRecruit()
    local state = RegionQuestMgr:GetInstance():GetRecruitState()
    if state == 0 then
        -- 开启招募需要判断保护时间
        if self.tc_RecruitProtect:IsRunning() then
            local time = self.tc_RecruitProtect:GetTime()
            GameUtils.Toast(localize("招募按钮冷却中 _num_秒", {_num_ = 3 - time}))
            return
        end
    end
    
    if state == 1 then
        self.tc_RecruitProtect:Stop()
        self.tc_RecruitProtect:Start(3)
    end

    RegionQuestMgr:GetInstance():RecruitReq()

end

--- 收到招募状态变化事件
---@param newState number
function UIActionTeamDestoryDialog:OnRegionRecruitResult(newState)
    self:SetRecruitBtnState(newState, true)
end

--- 招募按钮特效
---@param state any
function UIActionTeamDestoryDialog:EffectOnRecruitBtnStateChanged(state, showTrail)
    if state == 0 then
        self.anim_BtnRecruit:Stop()
        -- 关闭循环特效
        local loopEffect = self.anim_BtnRecruit.transform:Find("UIFX_LoopGlow")
        KTool.SetActive(loopEffect, false)
        -- 拖尾特效位置还原
        local trailEffect = loopEffect:Find("UIFX_Number_BoomMove")
        trailEffect.localPosition = Vector3.zero
        -- 关闭爆炸特效
        if isNotNull(self.anim_Container) then
            self.anim_Container:Stop()
            self.anim_Container:Play("ActionTeamDestoryDialog_OverseaChatBtnGlowDefault")
        end
    elseif state == 1 then
        self.anim_BtnRecruit:Play(RecruitBtnAnimation)
        -- 拖尾
        local trailEffect = self.anim_BtnRecruit.transform:Find("UIFX_LoopGlow/UIFX_Number_BoomMove")
        KTool.SetActive(trailEffect, showTrail)
        if showTrail then
            -- 移动拖尾特效
            local chatIcon = self.BtnChat:Find("Button/ImgChat")
            if isNotNull(chatIcon) then
                trailEffect:DOMove(chatIcon.position, 0.38, false):OnComplete(function()
                    -- 播放爆炸特效
                    if isNotNull(self.anim_Container) then
                        self.anim_Container:Play("ActionTeamDestoryDialog_OverseaChatBtnGlow")
                    end
                    -- 隐藏拖尾特效
                    KTool.SetActive(trailEffect, false)
                end)
            end
        end
    end
end

function UIActionTeamDestoryDialog:OnLoadBegin()
    self._isBegin = true
    local state = RegionQuestMgr:GetInstance():GetHouseState()
    --单人开始
    if state == HouseState.None then
        CfUtils.SetActive(self.LeftPanel, false)
    --双人开始
    elseif state == HouseState.ReadySuc then
        CfUtils.SetActive(self.LeftPanel, false)
    end
    CfUtils.SetActive(self.Before, false)
    CfUtils.SetActive(self.After, true)

    CfUtils.SetActive(self.TitleGroup, false)
    CfUtils.SetActive(self.BtnChat, false)
    CfUtils.SetActive(self.LeftGroup, false)
    CfUtils.SetActive(self.RightGroup, false)
    CfUtils.SetActive(self.TxtTime2, false)
    CfUtils.SetActive(self.LoadingGroup, true)
    CfUtils.SetActive(self.LoadingGroup2, true)
    local scr = CfUtils.GetLuaScr(self.PlayerGroup2, "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestoryNode")
    if scr then
        scr:FillLoad()
    end

    local scr = CfUtils.GetLuaScr(self.PlayerGroup, "Game.UI.FightReady.UIMainChapter.ActionTeamDestoryDialog.UIActionTeamDestoryNode")
    if scr then
        scr:FillLoad()
    end

    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UIActionTeamDestoryDialog:OnLoading(data)
    data = checkTable(data)
    if checkNumber(data.type) == 1 then   --自己
        self.ImgLoad2.fillAmount = checkNumber(data.num)
        CfUtils.FillText(self.TxtNum2, data.num)
    else
        self.ImgLoad.fillAmount = checkNumber(data.num)
        CfUtils.FillText(self.TxtNum, data.num)
    end
end

function UIActionTeamDestoryDialog:SetStateEnterBattle(state)
    self._enterBattle = state
end

function UIActionTeamDestoryDialog:OnAppQuit()
    RegionQuestMgr:GetInstance():QuitReq()
end

function UIActionTeamDestoryDialog:UpdateResources()
    if isNotNull(self.comp) then
        CfUtils.RefreshTopGoods(self.comp:GetResources())
    end
end

return UIActionTeamDestoryDialog
